// FIRRTL _ext wrappers using la_dpram / la_spram lambdalib interfaces

//////////////////////////////////////////////////////////////////////
// cc_banks_0_ext -> 2560x128 -> split 2x 2560x64
// NOTE: FakeRAM7 has no 2560-depth macro; closest is dp_4096x64.
// Adjust AW/depth as appropriate for your flow.
//////////////////////////////////////////////////////////////////////
module cc_banks_0_ext (
  input  [11:0] R0_addr,
  input         R0_en,
  input         R0_clk,
  output [127:0] R0_data,

  input  [11:0] W0_addr,
  input         W0_en,
  input         W0_clk,
  input  [127:0] W0_data
);

  wire [63:0] rdata_lo, rdata_hi;

  la_dpram #(.DW(64), .AW(12)) mem_lo (
    .wr_clk  (W0_clk),
    .wr_ce   (W0_en),
    .wr_we   (1'b1),
    .wr_addr (W0_addr),
    .wr_din  (W0_data[63:0]),
    .wr_wmask({64{1'b1}}),

    .rd_clk  (R0_clk),
    .rd_ce   (R0_en),
    .rd_addr (R0_addr),
    .rd_dout (rdata_lo),

    .vss(1'b0), .vdd(1'b1), .vddio(1'b1),
    .ctrl('0), .test('0)
  );

  la_dpram #(.DW(64), .AW(12)) mem_hi (
    .wr_clk  (W0_clk),
    .wr_ce   (W0_en),
    .wr_we   (1'b1),
    .wr_addr (W0_addr),
    .wr_din  (W0_data[127:64]),
    .wr_wmask({64{1'b1}}),

    .rd_clk  (R0_clk),
    .rd_ce   (R0_en),
    .rd_addr (R0_addr),
    .rd_dout (rdata_hi),

    .vss(1'b0), .vdd(1'b1), .vddio(1'b1),
    .ctrl('0), .test('0)
  );

  assign R0_data = {rdata_hi, rdata_lo};

endmodule

