  input  [6:0]  R0_addr,
  input         R0_en,
  input         R0_clk,
  output [63:0] R0_data,

  input  [6:0]  W0_addr,
  input         W0_en,
  input         W0_clk,
  input  [63:0] W0_data,
  input  [63:0] W0_mask
);

  la_spram #(.DW(64), .AW(7)) mem (
    .clk   (W0_clk),
    .ce    (W0_en | R0_en),
    .we    (W0_en),
    .wmask (W0_mask),
    .addr  (W0_en ? W0_addr : R0_addr),
    .din   (W0_data),
    .dout  (R0_data),

    .vss(1'b0), .vdd(1'b1), .vddio(1'b1),
    .ctrl('0), .test('0)
  );

endmodule

//////////////////////////////////////////////////////////////////////
// mem_0_ext -> huge DRAM stub (not synthesized, timing only)
//////////////////////////////////////////////////////////////////////
module mem_0_ext (
  input        [27:0] R0_addr,
  input               R0_en,
  input               R0_clk,
  output reg   [7:0]  R0_data,

  input        [27:0] W0_addr,
  input               W0_en,
  input               W0_clk,
  input        [7:0]  W0_data,
  input        [7:0]  W0_mask
);

  // timing-only stub - not mapped to any macro
  always @(posedge R0_clk) R0_data <= 8'h00;

endmodule